{
  "summary": "Renewal request from Acme Cloud Services proposing a 12% price increase for a 12-month extension; need to verify current contract terms, pricing, SLA performance, and any credits owed before drafting a response.",
  "reply_type": "vendor_email",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "List and read the current Acme Cloud Services contract (end date, pricing, renewal/price-increase clauses, notice periods), any pricing or procurement policy documents on acceptable increases, recent invoices to confirm current billing amount and currency, and SLA performance records; use the SLA credit calculator to determine any credits owed to us; if amounts are in USD or another foreign currency, use the currency converter to get local currency equivalents.",
      "why": "All facts needed for a renewal response—current terms, pricing, policy limits on increases, and any SLA credits—must be gathered before a counter-response can be drafted."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Draft the vendor email response to Acme Cloud Services acknowledging the renewal request, referencing the current contract terms and pricing, addressing the proposed 12% increase (accepting, countering, or requesting justification per policy), noting any SLA credits owed, and proposing next steps for confirmation.",
      "why": "The executor synthesizes the retrieved facts into the final reply for human review and approval."
    }
